#[allow(clippy::missing_errors_doc)]
#[pyfunction]
#[pyo3(signature = (html, options=None, visitor=None))]
pub fn convert(
    html: String,
    options: Option<ConversionOptions>,
    visitor: Option<Py<PyAny>>,
) -> PyResult<ConversionResult> {
    if let Some(obj) = visitor.as_ref() {
        let provides_any = Python::attach(|py| {
            let bound = obj.bind(py);
            [
                "visit_text",
                "visit_element_start",
                "visit_element_end",
                "visit_link",
                "visit_image",
                "visit_heading",
                "visit_code_block",
                "visit_code_inline",
                "visit_list_item",
                "visit_list_start",
                "visit_list_end",
                "visit_table_start",
                "visit_table_row",
                "visit_table_end",
                "visit_blockquote",
                "visit_strong",
                "visit_emphasis",
                "visit_strikethrough",
                "visit_underline",
                "visit_subscript",
                "visit_superscript",
                "visit_mark",
                "visit_line_break",
                "visit_horizontal_rule",
                "visit_custom_element",
                "visit_definition_list_start",
                "visit_definition_term",
                "visit_definition_description",
                "visit_definition_list_end",
                "visit_form",
                "visit_input",
                "visit_button",
                "visit_audio",
                "visit_video",
                "visit_iframe",
                "visit_details",
                "visit_summary",
                "visit_figure_start",
                "visit_figcaption",
                "visit_figure_end",
            ]
            .iter()
            .any(|name| bound.hasattr(*name).unwrap_or(false))
        });
        if !provides_any {
            return Err(pyo3::exceptions::PyTypeError::new_err(
                "`visitor` must be an object that defines at least one `HtmlVisitor` method (visit_text, visit_element_start, visit_element_end, visit_link, visit_image, visit_heading, visit_code_block, visit_code_inline, visit_list_item, visit_list_start, visit_list_end, visit_table_start, visit_table_row, visit_table_end, visit_blockquote, visit_strong, visit_emphasis, visit_strikethrough, visit_underline, visit_subscript, visit_superscript, visit_mark, visit_line_break, visit_horizontal_rule, visit_custom_element, visit_definition_list_start, visit_definition_term, visit_definition_description, visit_definition_list_end, visit_form, visit_input, visit_button, visit_audio, visit_video, visit_iframe, visit_details, visit_summary, visit_figure_start, visit_figcaption, visit_figure_end); a bare callable is not accepted, because the bridge calls the methods by name",
            ));
        }
    }
    let visitor_object: Option<pyo3::Py<pyo3::PyAny>> = visitor;
    let visitor_handle: Option<html_to_markdown_rs::VisitorHandle> = match visitor_object {
        Some(obj) => {
            let bridge = PyHtmlVisitorBridge::new(obj);
            Some(std::sync::Arc::new(std::sync::Mutex::new(bridge)) as html_to_markdown_rs::VisitorHandle)
        }
        None => None,
    };
    let options_core: Option<html_to_markdown_rs::ConversionOptions> = options.map(|v| v.into());
    let options_core: Option<html_to_markdown_rs::ConversionOptions> = if let Some(handle) = visitor_handle {
        let mut opts = options_core.unwrap_or_default();
        opts.visitor = Some(handle);
        Some(opts)
    } else {
        options_core
    };
    html_to_markdown_rs::convert(&html, options_core)
        .map(|val| val.into())
        .map_err(conversion_error_to_py_err)
}

